// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 salt) public {
        // Adversarial counterparty: msg.sender of airDrop must expose supportsToken(),
        // so a plain fuzzed EOA cannot reach the guard. Deploy a minimal caller whose
        // address the token-qualifying modifier accepts; identity varied by fuzzed salt.
        Caller actor = new Caller{salt: bytes32(keccak256(abi.encode(salt)))}();
        bool ok;
        try actor.go(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: any qualifying caller starting from zero balance successfully
        // completes airDrop and ends with exactly 20 tokens.
        assertTrue(ok && c.tokenBalance(address(actor)) == 20);
    }
}

contract Caller {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function go(address target) external {
        ModifierEntrancy(target).airDrop();
    }
}
